insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('d114304d-e6f7-4461-8d7a-c994a7d2f21b', '230dd47d-f529-49f3-96ff-7e317dac819f', $$inleiding — ethyllactaat voor reiniging printplaten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context1.png$$,
   $$In de elektronica-industrie worden printplaten gemaakt. Tijdens het productieproces van deze printplaten worden hydrofobe stoffen gebruikt die later weer verwijderd moeten worden. Voor het verwijderen van deze stoffen kan ethyllactaat worden gebruikt. Ethyllactaat wordt gevormd uit melkzuur (C₃H₆O₃) en ethanol. Hieronder zijn de structuurformules van melkzuur en ethyllactaat weergegeven.$$, 'inline'),
  ('5d24f9ed-7c04-41aa-bbf0-dc40f8b49888', '230dd47d-f529-49f3-96ff-7e317dac819f', $$structuurformules — melkzuur en ethyllactaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context2.png$$,
   $$Structuurformules van melkzuur (HO−C(=O)−CH(OH)−CH₃) en ethyllactaat (CH₃−CH₂−O−C(=O)−CH(OH)−CH₃).$$, 'inline'),
  ('775a2465-4780-4859-9af4-b13dc6a3854b', '230dd47d-f529-49f3-96ff-7e317dac819f', $$melkzuur uit sacharose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context3.png$$,
   $$Melkzuur wordt op industriële schaal gemaakt door omzetting van sachariden met behulp van micro-organismen. Een voorbeeld van zo'n sacharide is sacharose (C₁₂H₂₂O₁₁). Voor de omzetting van sacharose tot melkzuur is ook water nodig.$$, 'inline'),
  ('91131e8b-8355-4cb0-a1c1-b59f7a141c6d', '230dd47d-f529-49f3-96ff-7e317dac819f', $$ethyllactaat mengbaar met hydrofobe stof en water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context4.png$$,
   $$Ethyllactaat heeft een uitstekend reinigend vermogen. Bovendien is ethyllactaat zowel met hydrofobe stoffen als met water mengbaar. Een voorwerp dat gereinigd is met ethyllactaat, kan daarna gespoeld worden met water.$$, 'inline'),
  ('652d4fc6-042d-4530-8a54-f2e0dd5d37f7', '230dd47d-f529-49f3-96ff-7e317dac819f', $$reactie 1 — vergelijking vorming ethyllactaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context5.png$$,
   $$In een fabriek kan ethyllactaat volgens een continuproces worden gemaakt uit melkzuur en ethanol. De vergelijking van deze omzetting is hieronder weergegeven. C₃H₆O₃ + C₂H₆O → C₅H₁₀O₃ + H₂O (reactie 1)$$, 'inline'),
  ('81fca3ab-4e56-45bb-9cfc-1d7db7588a2c', '230dd47d-f529-49f3-96ff-7e317dac819f', $$blokschema R1 — nevenreacties esters$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context6.png$$,
   $$Op de uitwerkbijlage bij dit examen is het onvolledige blokschema van het continuproces weergegeven. In dit blokschema ontbreken enkele stofstromen en de namen van de bijbehorende stoffen. In reactor R1 worden een ruime overmaat ethanol en een melkzuuroplossing geleid. In aanwezigheid van een katalysator wordt het reactiemengsel krachtig geroerd. Hierbij wordt een groot deel van het melkzuur omgezet tot ethyllactaat. Ook treden nevenreacties op waarbij esters ontstaan, zoals de ester van twee moleculen melkzuur.$$, 'inline'),
  ('00df5362-627d-4a6e-bda1-589ed3a1fe3e', '230dd47d-f529-49f3-96ff-7e317dac819f', $$verdamping in scheidingsruimte S1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context7.png$$,
   $$Voortdurend wordt een deel van het reactiemengsel uit reactor R1 overgebracht naar scheidingsruimte S1. Dit reactiemengsel bestaat uit ethanol, ethyllactaat, melkzuur, water en de esters die zijn ontstaan door nevenreacties. In scheidingsruimte S1 verdampen water, ethanol en ethyllactaat.$$, 'inline'),
  ('6a766948-f0b7-4d03-ba46-1fdff1da0e1d', '230dd47d-f529-49f3-96ff-7e317dac819f', $$recirculatie naar R1, S2 en S3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context8.png$$,
   $$De stoffen die niet verdampen, worden vanuit scheidingsruimte S1 teruggevoerd naar reactor R1. In reactor R1 wordt een gedeelte van de esters die zijn ontstaan door nevenreacties, omgezet tot melkzuur. De damp uit scheidingsruimte S1 wordt naar scheidingsruimte S2 gebracht. Hier wordt ethyllactaat als vloeistof afgescheiden. In scheidingsruimte S3 worden water en ethanol gescheiden. Water wordt afgevoerd.$$, 'inline'),
  ('ba3070fc-d621-4fea-8cce-97d0d22f0105', '230dd47d-f529-49f3-96ff-7e317dac819f', $$atoomeconomie en duurzaamheid$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context9.png$$,
   $$Volgens de fabrikant kan de productie van ethyllactaat duurzaam worden genoemd. De fabrikant onderbouwt deze bewering aan de hand van de atoomeconomie van reactie 1.$$, 'inline'),
  ('793424ca-5f8c-4e1f-986f-5fae4a7a2e38', '230dd47d-f529-49f3-96ff-7e317dac819f', $$uitgangspunt 2 groene chemie — plantaardige sachariden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context10.png$$,
   $$Volgens de fabrikant voldoet het proces door de hoge atoomeconomie aan uitgangspunt 2 van de groene chemie. Omdat de fabrikant plantaardige sachariden gebruikt, kan hij ook een ander uitgangspunt van de groene chemie als argument gebruiken om de productie van ethyllactaat duurzaam te noemen.$$, 'inline'),
  ('411d87aa-3a51-4a6a-94f3-3cab9fe24998', '230dd47d-f529-49f3-96ff-7e317dac819f', $$uitwerkbijlage vraag 5 — blokschema continuproces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-context11.png$$,
   $$Blokschema op de uitwerkbijlage bij vraag 5: onvolledig blokschema van het continuproces. Ingaande pijlen 'ethanol' en 'melkzuuroplossing' naar reactor R1; R1 is verbonden met scheidingsruimte S1 (pijl van R1 naar S1, en een terugvoerpijl van S1 naar R1); vanuit S1 gaat een pijl naar S2, vanuit S2 een pijl omhoog naar S3 en een pijl naar rechts (uitgaande stroom); de pijlen en stofnamen voor de overige stofstromen (ethyllactaat, melkzuur, esters, water) ontbreken nog en moeten worden aangevuld. Vraagnummer 5 staat linksboven, met ruime witruimte eronder voor het aanvullen van het schema.$$, 'uitwerkbijlage'),

  ('66866e12-0e6e-4d59-9381-39cdc90e8ee2', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$inleiding — lithium-ionbatterij$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context1.png$$,
   $$In veel mobiele telefoons zit een lithium-ionbatterij. Deze batterijen zijn licht, kunnen veel energie leveren en zijn snel op te laden. Het basisontwerp van een lithium-ionbatterij is in figuur 1 schematisch weergegeven.$$, 'inline'),
  ('9dfcd5d1-e6ad-443c-8871-411fbaa142f4', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$figuur 1 — basisontwerp lithium-ionbatterij$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context2.png$$,
   $$figuur 1: schematische weergave van het basisontwerp van een lithium-ionbatterij. Elektrode A en elektrode B, met daartussen het elektrolyt, zijn via een energieverbruiker met elkaar verbonden in een gesloten kring.$$, 'inline'),
  ('8d9480eb-a61a-45fd-b079-5b866efd9d04', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$elektrode A en B, elektrolyt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context3.png$$,
   $$Elektrode A bevat onder andere het metaal lithium (Li). Elektrode B bevat Li⁺-ionen. Tussen beide elektroden bevindt zich een elektrolyt, dat bestaat uit een polymeer waarin zich een vloeibaar lithiumzout bevindt.$$, 'inline'),
  ('1dd89b54-8d2b-4a4e-8d3a-d9bcf4455f22', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$PEO polymeer en polaire atoombinding$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context4.png$$,
   $$Een veelgebruikt polymeer is PEO. De formule van PEO is (CH₂CH₂O)ₙ. In figuur 2 is een vergroting van het elektrolyt schematisch weergegeven. Hierin is te zien hoe een Li⁺-ion van polymeerketen naar polymeerketen wordt doorgegeven, doordat telkens een ander groepje O-atomen het Li⁺-ion bindt. De binding komt tot stand doordat de O-atomen in PEO enigszins negatief geladen zijn. Dit is het gevolg van een polaire atoombinding tussen de C-atomen en de O-atomen in PEO. Tijdens de stroomlevering bewegen Li⁺-ionen van elektrode A naar elektrode B.$$, 'inline'),
  ('46787c53-4ed6-4a9d-977d-2e5488f68aa8', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$figuur 2 — Li⁺-ion transport tussen polymeerketens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context5.png$$,
   $$figuur 2: schematische vergroting van het elektrolyt, met drie PEO-polymeerketens (keten 1, 2 en 3), elk met groepjes O-atomen verbonden via R (CH₂CH₂)-eenheden. Links bindt een Li⁺-ion aan een groepje O-atomen van keten 1; na verplaatsing naar rechts in de batterij tijdens stroomlevering bindt hetzelfde Li⁺-ion aan een groepje O-atomen van keten 2.$$, 'inline'),
  ('ad31376c-cc1f-441a-a648-63288a259fca', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$polyetheen als elektrisch geleidend polymeer?$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context6.png$$,
   $$Een docente bespreekt met haar leerlingen de elektrische geleiding in PEO. Een leerling vraagt of polyetheen ook gebruikt kan worden als elektrisch geleidend polymeer.$$, 'inline'),
  ('9282d49a-2968-4119-b2e7-8960c823eb75', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$halfreacties 1 en 2 — lithium-ionbatterij$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context7.png$$,
   $$De halfreacties die in deze batterij optreden tijdens stroomlevering zijn hieronder vereenvoudigd weergegeven: halfreactie 1: LiC₆ → 6C + Li⁺ + e⁻. halfreactie 2: CoO₂ + Li⁺ + e⁻ → LiCoO₂.$$, 'inline'),
  ('7fdf78a9-df15-440e-9a1a-3a75ddbf80c1', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$CoO₂ en LiCoO₂ als zouten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context8.png$$,
   $$CoO₂ kan worden opgevat als een zout dat bestaat uit kobaltionen en oxide-ionen. LiCoO₂ kan worden opgevat als een zout dat bestaat uit lithiumionen, kobaltionen en oxide-ionen. Uit de formules CoO₂ en LiCoO₂ kan worden afgeleid dat de kobaltionen in CoO₂ en in LiCoO₂ niet dezelfde lading hebben.$$, 'inline'),
  ('2abb29af-9671-46b4-addf-12730eba1dc4', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$0,053 mol elektronen — batterij$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context9.png$$,
   $$In een bepaalde lithium-ionbatterij kan maximaal 0,053 mol elektronen worden overgedragen tussen de twee elektroden, voordat deze batterij weer opgeladen moet worden.$$, 'inline'),
  ('6319a9ba-4240-411e-aa4f-e6c4be8c1ec7', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$brandgevaar lithium-ionbatterijen — PEO ontbrandt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context10.png$$,
   $$Veel luchtvaartmaatschappijen hebben vanwege brandgevaar speciale eisen gesteld aan het vervoeren van oplaadbare lithium-ionbatterijen in het laadruim van passagiersvliegtuigen. Het polymeer PEO ontbrandt namelijk gemakkelijk. Bovendien kan de warmte die bij de verbranding vrijkomt ervoor zorgen dat ook andere batterijen ontbranden.$$, 'inline'),
  ('0ed675b0-966f-4e38-b297-90e1cd649a72', 'c4bd66d3-2aed-4926-b6ae-2611cf5c604d', $$figuur 3 — vier energiediagrammen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-lithium-ionbatterij-context11.png$$,
   $$In figuur 3 staan vier energiediagrammen. In deze diagrammen behoort het linker energieniveau bij de beginstoffen en het rechter energieniveau bij de reactieproducten. figuur 3: vier energiediagrammen (diagram a, b, c en d) met energie (E) op de y-as. Diagram a: kleine activeringsenergie, licht exotherm (product iets lager dan beginstoffen). Diagram b: kleine activeringsenergie, sterk exotherm (product duidelijk lager). Diagram c: grote activeringsenergie, licht exotherm. Diagram d: grote activeringsenergie, sterk exotherm.$$, 'inline'),

  ('9ba49771-7041-4f2a-83eb-6cc017e89b71', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$inleiding — schaliegas en fracking$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context1.png$$,
   $$Schaliegas is aardgas dat in gesteente diep onder het aardoppervlak is opgesloten. Om schaliegas te winnen gebruikt men een methode die fracking wordt genoemd. Hierbij wordt een mengsel van water, zand en chemicaliën onder hoge druk in het gesteente gepompt zodat hierin scheurtjes ontstaan en het schaliegas vrijkomt. Bij fracking ontstaan grote hoeveelheden afvalwater dat onder andere Br⁻-ionen, Cl⁻-ionen en I⁻-ionen bevat. Deze ionen zijn afkomstig van goed oplosbare zouten die in het gesteente voorkomen.$$, 'inline'),
  ('a8941044-54e2-4635-ace4-19d01d1cef1f', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$frackinglocaties — monsters en methode tekstfragment 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context2.png$$,
   $$Op frackinglocaties worden regelmatig monsters van het grondwater genomen. Om op de frackinglocatie snel het bromidegehalte van het grondwater te bepalen is de methode ontwikkeld die in tekstfragment 1 is beschreven.$$, 'inline'),
  ('04fa60d7-ac9e-4b50-ab32-7449f41b8414', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$tekstfragment 1 — bepaling bromidegehalte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context3.png$$,
   $$tekstfragment 1: 1 Men maakt gebruik van filtreerpapiertjes waarop eerst een oplossing van chloramine-T en de zuur-base-indicator fenolrood is aangebracht en die men daarna heeft laten drogen. 2 Een druppel grondwater wordt op zo'n filtreerpapiertje aangebracht. Eventueel wordt het grondwater eerst verdund. 3 In aanwezigheid van Br⁻ vinden achtereenvolgens twee reacties plaats: Reactie 1: Br⁻ wordt door een reactie met chloramine-T omgezet tot onder andere broom. Reactie 2: het ontstane broom reageert volledig met fenolrood tot onder andere broomfenolblauw. 4 Door beide reacties wordt het gele filtreerpapiertje enigszins blauw. 5 De afname van de gele kleur wordt gemeten met een kleurdetector. 6 Met behulp van een ijklijn wordt het bromidegehalte bepaald.$$, 'inline'),
  ('36723ba5-29c5-4857-be60-0ad9337d4500', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$pH 4,6 — broomfenolblauw blauwe kleur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context4.png$$,
   $$De oplossing waarin de reacties plaatsvinden, heeft een pH van 4,6. Het ontstane broomfenolblauw heeft bij deze pH een blauwe kleur.$$, 'inline'),
  ('63426493-f4be-42e6-8475-7f219495591a', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$reactie 2 — fenolrood + broom naar broomfenolblauw$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context5.png$$,
   $$Reactie 2 is een reactie van fenolrood (C₁₉H₁₄O₅S) met broom. Daarbij worden per molecuul fenolrood vier H-atomen vervangen door vier Br-atomen. Bij reactie 2 ontstaan broomfenolblauw en één andere stof. Deze reactie is vergelijkbaar met de substitutiereactie van een alkaan met een halogeen en is op de uitwerkbijlage onvolledig weergegeven.$$, 'inline'),
  ('4e71ef14-16c5-4390-8174-f9bae25e7c69', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$10 massa-ppm grenswaarde meetmethode$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context6.png$$,
   $$De hoeveelheden chloramine-T en fenolrood die op het filtreerpapiertje zijn aangebracht, zijn zo gekozen dat bromidegehaltes tot maximaal 10 massa-ppm gemeten kunnen worden. Wanneer bij punt 2 een grondwatermonster met een bromidegehalte hoger dan 10 massa-ppm wordt aangebracht, zal een onjuist bromidegehalte worden gemeten.$$, 'inline'),
  ('4ca07217-b83a-482d-8016-c1b43232d911', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$figuur 1 — ijklijn kleurintensiteit tegen bromidegehalte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context7.png$$,
   $$In figuur 1 is de ijklijn weergegeven die is gemaakt met behulp van een aantal oplossingen met elk een bekend bromidegehalte. In de figuur is het bromidegehalte uitgezet tegen de kleurintensiteit. De kleurintensiteit komt overeen met een bepaalde hoeveelheid van de beginstof fenolrood, die afneemt naarmate er meer bromide aanwezig is. Figuur 1: grafiek met op de y-as de kleurintensiteit (schaal met onderbreking, van 165 tot 190) en op de x-as het bromidegehalte in massa-ppm (0 tot 10). De ijklijn loopt vanaf ongeveer (0, 186) dalend naar ongeveer (10, 168), met meetpunten dicht bij de lijn.$$, 'inline'),
  ('4361f523-0013-4d0a-a3dc-d128ccaa76d5', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$wetenschapper — verdunning en kleurintensiteit 180$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context8.png$$,
   $$Een wetenschapper onderzoekt het bromidegehalte van een grondwatermonster. Hij voert de bepaling uit tekstfragment 1 uit. Bij punt 2 verdunt hij het grondwatermonster door in een reageerbuisje 2,00 mL grondwater met 8,00 mL gedestilleerd water te mengen. Hij meet vervolgens een kleurintensiteit van 180. Met behulp van de grafiek en de beschreven verdunning berekent hij het bromidegehalte van het grondwatermonster, in massa-ppm.$$, 'inline'),
  ('e34bcb24-7d2d-4e9c-a96e-e5116f6c3d6a', '29d3539a-4cee-44f2-b957-909a5ab04d29', $$uitwerkbijlage vraag 21 — vergelijking reactie 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-bromide-in-grondwater-context9.png$$,
   $$Uitwerkbijlage bij vraag 21: onvolledige reactievergelijking van reactie 2, met molecuulformules: C₁₉H₁₄O₅S + … → … + …. Vraagnummer 21 staat linksboven, met ruime witruimte eronder voor het aanvullen van de vergelijking.$$, 'uitwerkbijlage'),

  ('264e37c6-9153-45e5-b812-f3e787834642', '67f20952-1820-4ed5-b449-0152bef6b51f', $$inleiding — TTI sticker$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context1.png$$,
   $$Hoeveel dagen kun je een verse salade bewaren? En in hoeverre wordt de houdbaarheid beïnvloed door de temperatuur? Een tijd-temperatuur-indicator (TTI), ontworpen door Andrew Mills, laat dit in een oogopslag zien. Deze TTI is een blauwgekleurde, temperatuurgevoelige sticker. Zolang de sticker blauw is, is de salade vers. Als de sticker naar groen of zelfs geel is verkleurd, dan is de salade bedorven. De TTI bestaat uit twee lagen (zie figuur 1). De toplaag van de sticker bestaat uit een folie waarop een mengsel van polymeer A en ammoniumwaterstofcarbonaat (NH₄HCO₃) is aangebracht. De kleurlaag bestaat uit een folie waarop een mengsel van polymeer B, een weekmaker en de indicator broomfenolblauw (BFB) is aangebracht.$$, 'inline'),
  ('688edaf5-83ab-42d0-ae6c-473e0bc29423', '67f20952-1820-4ed5-b449-0152bef6b51f', $$figuur 1 — opbouw TTI (toplaag/kleurlaag)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context2.png$$,
   $$figuur 1: opbouw van de TTI in twee lagen. De toplaag bestaat (van boven naar onder) uit een folie en een laag met polymeer A en NH₄HCO₃. De kleurlaag bestaat uit een laag met polymeer B, weekmaker en BFB, en een folie eronder.$$, 'inline'),
  ('bc5bb2a8-9fc9-43e9-9c41-198dd1a5b2dc', '67f20952-1820-4ed5-b449-0152bef6b51f', $$toplaag houdt TTI blauw — reactie 1 en 2 intro$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context3.png$$,
   $$De toplaag van de sticker houdt de TTI blauw zolang de TTI niet wordt gebruikt. Dit komt doordat in deze laag een reactie optreedt waarbij ammoniak ontstaat (reactie 1). Deze ammoniak wordt door de kleurlaag opgenomen en kleurt de indicator (BFB) blauw (reactie 2).$$, 'inline'),
  ('0d98a387-64c6-4654-a9cb-0be7782082f9', '67f20952-1820-4ed5-b449-0152bef6b51f', $$reactie 1 en reactie 2 — vergelijkingen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context4.png$$,
   $$NH₄HCO₃ (s) → NH₃(g) + CO₂(g) + H₂O(g) (reactie 1). NH₃ + BFB → NH₃BFB (reactie 2) (geel) (blauw).$$, 'inline'),
  ('302185f7-4ad2-4ca6-91fa-56e749d600b3', '67f20952-1820-4ed5-b449-0152bef6b51f', $$reactie 1 verloopt langzaam$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context5.png$$,
   $$Reactie 1 verloopt langzaam, waardoor een ongebruikte sticker maandenlang houdbaar blijft.$$, 'inline'),
  ('1b4f75f6-465c-4d75-a60a-3d483dc673cc', '67f20952-1820-4ed5-b449-0152bef6b51f', $$winkelier verwijdert toplaag — reactie 3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context6.png$$,
   $$Een winkelier plakt de TTI op een bakje verse salade en verwijdert de toplaag van de sticker. Daarna verkleurt de indicator geleidelijk van blauw via groen tot geel doordat het gele BFB volgens reactie 3 wordt teruggevormd. Door de kleurverandering wordt zichtbaar hoe vers het product is.$$, 'inline'),
  ('9e4f2021-271c-402b-a9a7-ecdc73a6d425', '67f20952-1820-4ed5-b449-0152bef6b51f', $$reactie 3 — vergelijking$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context7.png$$,
   $$NH₃BFB → NH₃ + BFB (reactie 3) (blauw) (geel).$$, 'inline'),
  ('4905ec02-54ff-45f9-b199-f58e1326828f', '67f20952-1820-4ed5-b449-0152bef6b51f', $$activeringsenergie reactie 3 vergelijkbaar met voedselbederf$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context8.png$$,
   $$De activeringsenergie van reactie 3 is ongeveer even groot als de activeringsenergie van reacties die plaatsvinden tijdens voedselbederf. Wanneer in plaats van BFB een andere indicator wordt gebruikt, die verkleurt door een reactie met een aanzienlijk hogere activeringsenergie, zou de TTI minder betrouwbaar zijn.$$, 'inline'),
  ('84fe68d5-b67f-401b-b497-a9ae31881306', '67f20952-1820-4ed5-b449-0152bef6b51f', $$weekmaker en vrijkomen van ammoniak uit kleurlaag$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context9.png$$,
   $$Door het verwijderen van de toplaag kunnen de ammoniakmoleculen die bij reactie 3 ontstaan in de omgevingslucht vrijkomen. Hierdoor is er steeds minder NH₃BFB en zal de TTI steeds geler kleuren. Om vrij te kunnen komen in de omgevingslucht moeten de ammoniakmoleculen door de kleurlaag heen bewegen. Dit gaat gemakkelijker wanneer het polymeer waaruit de kleurlaag bestaat een weekmaker bevat.$$, 'inline'),
  ('4c0fb42c-41ae-40af-871b-c0799cb0beda', '67f20952-1820-4ed5-b449-0152bef6b51f', $$geurdrempel ammoniak$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-groen-is-niet-vers-context10.png$$,
   $$Uit de TTI komt een kleine hoeveelheid ammoniak vrij. Ammoniak heeft een indringende geur en een lage geurdrempel. De geurdrempel is de laagste concentratie van een gasvormige stof in lucht die waarneembaar is voor de mens. Toch zal de lucht in een koelkast volgens Andrew Mills niet naar ammoniak gaan ruiken, zelfs niet als een koelkast veel TTI's bevat.$$, 'inline'),

  ('c052ecff-817a-451e-831a-48bbb8d6aa0c', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$indeling voedingsstoffen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context1.png$$,
   $$Voedsel bevat de voedingsstoffen die het lichaam nodig heeft. Deze voedingsstoffen kunnen op basis van de chemische structuur in drie groepen worden ingedeeld. De eiwitten vormen een van deze groepen.$$, 'inline'),
  ('8330e832-d155-42ea-a5ed-e51606335906', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$zure maagvloeistof — zoutzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context2.png$$,
   $$Tijdens het eten belandt voedsel via de mond in de maag. De vloeistof in de maag is zuur, doordat bepaalde cellen van de maagwand zoutzuur afgeven. Dit zoutzuur kan worden opgevat als een oplossing die 5,8 g HCl per liter bevat.$$, 'inline'),
  ('302b9850-0c46-4636-a16b-bbd5139e06c7', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$pepsine enzym — afbraak eiwitten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context3.png$$,
   $$De zure maagvloeistof bevat ook het enzym pepsine. Pepsine is een eiwit dat de afbraak van voedseleiwitten versnelt. Bij deze afbraak wordt steeds een binding tussen twee aminozuureenheden in de keten van een voedseleiwitmolecuul verbroken.$$, 'inline'),
  ('b742baaf-9884-4d73-8311-8545ad21983e', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$mechanisme pepsine-afbraak in 2 stappen — figuur 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context4.png$$,
   $$Het verbreken van deze bindingen is een proces dat in 2 stappen verloopt. Dit proces is vereenvoudigd weergegeven in figuur 1. In figuur 1 zijn ook twee zijgroepen van het pepsinemolecuul weergegeven. Zijgroep A is geïoniseerd doordat deze een H⁺-ion heeft afgestaan.$$, 'inline'),
  ('5fe2f763-b578-4f55-8b38-37c1d39cfdbe', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$figuur 1 — mechanisme stap 1 en stap 2 van peptidehydrolyse$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context5.png$$,
   $$figuur 1: vereenvoudigd mechanisme van de afbraak van een peptidebinding door pepsine, in twee stappen. Voor stap 1: het voedseleiwitmolecuul (R₁−NH−CO−R₂) bevindt zich tussen twee zijgroepen van het pepsinemolecuul (zijgroep A, geïoniseerd/negatief geladen O⁻, en zijgroep B, met een OH-groep); een watermolecuul (H−O−H) ligt tussen de carbonylgroep en zijgroep A. In stap 1 valt het water aan op het carbonyl-koolstofatoom, met verplaatsing van elektronenparen tussen zijgroep A en het watermolecuul, waarbij een tussenproduct met een OH en een extra H op de stikstof ontstaat en zijgroep B nu negatief geladen is. In stap 2 valt dit uiteen tot de twee losse aminozuurfragmenten (R₁−NH₂ en R₂−C(=O)−OH), waarbij zijgroep A weer het (nu extra) H-atoom heeft opgenomen en zijgroep B weer een OH-groep heeft.$$, 'inline'),
  ('79a6bf60-838e-4bbc-9a91-578666143134', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$pepsine — kenmerken uit tekst en figuur 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context6.png$$,
   $$Zowel uit de tekst van deze opgave als uit figuur 1 blijkt dat pepsine een enzym is.$$, 'inline'),
  ('4d26880a-4f70-494e-991c-9d864268ea5a', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$fragment eiwitmolecuul — Cys-Phe-Asp-Val-Phe-Lys-Glu$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context7.png$$,
   $$Hieronder is een fragment weergegeven van de primaire structuur van een eiwitmolecuul dat in voedsel kan voorkomen. ~Cys-Phe-Asp-Val-Phe-Lys-Glu~$$, 'inline'),
  ('8679b41c-5b58-48e2-afe6-2b3c27fa0f29', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$afgebroken tot Phe-Asp-Val$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context8.png$$,
   $$Dit fragment kan met behulp van een pepsinemolecuul worden afgebroken tot onder meer het onderstaande molecuul. Phe-Asp-Val$$, 'inline'),
  ('f873bc66-1dc0-41cd-ba39-db0625e71bb0', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$welke bindingen kan pepsine verbreken$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context9.png$$,
   $$Pepsinemoleculen kunnen niet tussen alle aminozuureenheden bindingen verbreken, maar wel: − de binding tussen twee aminozuureenheden met beide een hydrofobe zijgroep, − de binding tussen een aminozuureenheid met een hydrofobe zijgroep en een aminozuureenheid met een zwavelbevattende zijgroep.$$, 'inline'),
  ('50a6b3af-4c13-4c95-b8e2-1e0217c50f9a', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$alvleessap toegevoegd — pH-verandering darm$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context10.png$$,
   $$Na verloop van tijd belandt het deels verteerde voedsel vanuit de maag in de darm. Hier wordt het alvleessap toegevoegd (figuur 2), waardoor de pH in de darm anders is dan die in de maag. Door deze pH-verandering verandert de activiteit van pepsine. Dit is weergegeven in figuur 3.$$, 'inline'),
  ('99a4ddad-2147-4564-a6b4-14d0dbd110a4', 'a0c5c64a-52b0-4aba-af28-2903652c03d4', $$figuur 2 en figuur 3 — spijsverteringsstelsel en enzymactiviteit vs pH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-eiwitvertering-context11.png$$,
   $$figuur 2: schematische weergave van het spijsverteringsstelsel, met de maag (pH = 1,5 tot 3,5), het alvleessap dat wordt toegevoegd bij de darm, en de darm (pH tot 8,0). figuur 3: grafiek van de enzymactiviteit van pepsine (%) tegen de pH (0-8). De activiteit stijgt scherp van ongeveer 27% bij pH 1,2 naar 100% bij pH 2, daalt daarna geleidelijk naar ongeveer 66% bij pH 4,5-5, valt dan sterk terug naar bijna 0% vanaf pH 5,5 en blijft laag tot pH 8.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('0f8cb041-a5e3-44ca-8f39-27bcc3ed0f01', '230dd47d-f529-49f3-96ff-7e317dac819f', 1,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["melkzuur", "sacharose", "molecuulformule", "reactievergelijking", "sachariden"]'::jsonb,
   $$Opstellen van de reactievergelijking in molecuulformules voor de omzetting van sacharose en water tot melkzuur.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag1.png$$,
   $$Geef de vergelijking in molecuulformules van de omzetting van sacharose tot melkzuur.$$, array['d114304d-e6f7-4461-8d7a-c994a7d2f21b', '775a2465-4780-4859-9af4-b13dc6a3854b']::uuid[]),
  ('01c064c8-348c-4394-b8d4-847db0ecb2f5', '230dd47d-f529-49f3-96ff-7e317dac819f', 2,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["ethyllactaat", "hydrofoob", "hydrofiel", "polaire groep", "mengbaarheid"]'::jsonb,
   $$Verklaren waarom ethyllactaat zowel met hydrofobe stoffen als met water mengbaar is aan de hand van de structuurformule.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag2.png$$,
   $$Leg uit, aan de hand van de structuurformule, dat ethyllactaat zowel met een hydrofobe stof als met water mengbaar is.$$, array['5d24f9ed-7c04-41aa-bbf0-dc40f8b49888', '91131e8b-8355-4cb0-a1c1-b59f7a141c6d']::uuid[]),
  ('7ba4d674-d6f2-4487-a0f2-05e823df0ba9', '230dd47d-f529-49f3-96ff-7e317dac819f', 3,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["melkzuur", "ester", "condensatiereactie", "structuurformule", "veresteren"]'::jsonb,
   $$Tekenen van de structuurformule van de ester die ontstaat uit twee moleculen melkzuur (condensatiereactie).$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag3.png$$,
   $$Geef de structuurformule van de ester van twee moleculen melkzuur.$$, array['5d24f9ed-7c04-41aa-bbf0-dc40f8b49888', '81fca3ab-4e56-45bb-9cfc-1d7db7588a2c']::uuid[]),
  ('fc07ee05-1d50-466d-afa0-7b9af01c1013', '230dd47d-f529-49f3-96ff-7e317dac819f', 4,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["verdampen", "waterstofbrug", "vanderwaalsbinding", "intermoleculaire binding", "ethyllactaat"]'::jsonb,
   $$Benoemen van de twee typen intermoleculaire bindingen die verbroken worden bij het verdampen van het mengsel in S1.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag4.png$$,
   $$Geef de namen van de twee bindingstypen die worden verbroken bij het verdampen in scheidingsruimte S1.$$, array['00df5362-627d-4a6e-bda1-589ed3a1fe3e', '5d24f9ed-7c04-41aa-bbf0-dc40f8b49888']::uuid[]),
  ('721d1c52-7a8f-419c-93b7-18822e225601', '230dd47d-f529-49f3-96ff-7e317dac819f', 5,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["blokschema", "stofstromen", "continuproces", "recycling", "procesontwerp"]'::jsonb,
   $$Completeren van het blokschema van het continuproces met de ontbrekende stofstromen.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag5.png$$,
   $$Maak het blokschema op de uitwerkbijlage compleet.
− Teken de pijlen van de ontbrekende stofstromen. Houd daarbij rekening met hergebruik van stoffen.
− Noteer de nummers van de onderstaande stoffen bij de juiste pijlen.
1 ethanol
2 ethyllactaat
3 melkzuur
4 esters die zijn ontstaan door nevenreacties
5 water
− Alle nummers moeten meer dan één keer worden gebruikt.$$, array['81fca3ab-4e56-45bb-9cfc-1d7db7588a2c', '00df5362-627d-4a6e-bda1-589ed3a1fe3e', '6a766948-f0b7-4d03-ba46-1fdff1da0e1d', '411d87aa-3a51-4a6a-94f3-3cab9fe24998']::uuid[]),
  ('3c7db74c-a8f5-418c-a9f9-0a1d84e37aac', '230dd47d-f529-49f3-96ff-7e317dac819f', 6,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["atoomeconomie", "reactie 1", "molaire massa", "groene chemie", "rendement"]'::jsonb,
   $$Berekenen van de atoomeconomie van de vorming van ethyllactaat.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-i-ethyllactaat-vraag6.png$$,
   $$Bereken de atoomeconomie voor de vorming van ethyllactaat volgens reactie 1. Gebruik Binas-tabel 37H of ScienceData-tabel 1.7.7.$$, array['652d4fc6-042d-4530-8a54-f2e0dd5d37f7']::uuid[]),
  ('c0ad2aa0-d8ee-487e-b846-c3ba2862f48d', '230dd47d-f529-49f3-96ff-7e317dac819f', 7,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["atoomeconomie", "duurzaamheid", "groene chemie", "afval", "bijproducten"]'::jsonb,
